        color: #333;
        margin-bottom: 2px;
    }

    .customer-address {
        font-size: 10px;
        line-height: 1.4;
        color: #444;
    }

    .invoice-details {
        width: 100%;
        border-collapse: collapse;
        font-size: 10px;
    }

    .invoice-details td {
        border: 1px solid #222 !important;
        padding: 5px 10px;
        height: 26px;
    }

    .invoice-details .detail-label {
        width: 38%;
        background: #909090;
        color: white;
    }

    .invoice-details .detail-value {
        width: 62%;
        color: #222;
    }

    /* Item table */

    .item-table {
        width: 100%;
        border-collapse: collapse;
        table-layout: fixed;
        margin-bottom: 20px;
        border: 1px solid #111;
    }

    .item-table th {
        background: #929292;
        color: white;
        border: 1px solid #111;
        padding: 7px 6px;
        font-weight: normal;
        font-size: 10px;
        text-align: center;
    }

    .item-table td {
        padding: 8px 6px;
        vertical-align: top;
        border-left: none;
        border-right: none;
        border-top: none;
        border-bottom: none;
        font-size: 9.5px;
    }

    .item-table tbody tr:last-child td {
