    }

    .col-qty {
        width: 9%;
        text-align: center;
    }

    .col-rate {
        width: 13%;
        text-align: right;
    }

    .col-tax-rate {
        width: 9%;
        text-align: center;
    }

    .col-tax {
        width: 12%;
        text-align: right;
    }

    .col-amount {
        width: 13%;
        text-align: right;
    }

    .item-name {
        font-weight: 500;
        color: #222;
        margin-bottom: 2px;
    }

    .item-description {
        color: #555;
        line-height: 1.4;
        word-break: break-word;
    }

    /* Amount and totals */

    .summary-table {
        width: 100%;
        border-collapse: collapse;
        margin-top: 6px;
    }

    .summary-table td {
        border: none !important;
        padding: 0;
        vertical-align: top;
    }

    .amount-words-section {
        width: 67%;
        padding-top: 6px !important;
        padding-right: 20px !important;
        font-size: 10px;
    }

    .totals-section {
        width: 33%;
    }

    .amount-words-label {
        color: #555;
    }

    .amount-words-value {
        font-weight: bold;
        color: #333;
    }

    .totals-table {
        width: 100%;
        border-collapse: collapse;
        font-size: 10px;
    }

    .totals-table td {
        border: none !important;
        padding: 7px 5px;
        vertical-align: top;
    }

    .totals-label {
        width: 68%;
        text-align: right;
        padding-right: 12px !important;
    }

    .totals-value {
        width: 32%;
        text-align: right;
        white-space: nowrap;
    }

    .grand-total-row td {
        border-top: 2px solid #222 !important;
        padding-top: 8px;
        font-weight: bold;
    }

    .grand-total-amount {
        font-size: 12px;
        font-weight: bold;
    }

    /* Terms */

    .terms-section {
        margin-top: 28px;
        font-size: 8px;
        color: #444;
        page-break-inside: avoid;
    }

    .terms-title {
        font-size: 11px;
        color: #777;
        margin-bottom: 7px;
    }

    .terms-content {
        line-height: 1.45;
    }

    .thank-you {
        margin-top: 14px;
    }

    .signature {
        margin-top: 14px;
    }

    /* Page breaking */

    .item-table tr {
        page-break-inside: avoid;
    }

    .summary-table,
    .terms-section {
        page-break-inside: avoid;
    }

    @media print {
        body,
        .print-format {
            margin: 0;
            padding: 0;
        }

        .invoice-container {
            width: 100%;
        }
    }
</style>

<div class="invoice-container">

    <!-- Letterhead -->
<!--letterHeadfromImageAddedInthe-->
    <!--<table class="letterhead-table">-->
    <!--    <tr>-->
    <!--        <td class="logo-cell">-->
    <!--            <img-->
    <!--                src="/private/files/arabscale_logo.png"-->
    <!--                class="logo-image"-->
    <!--                alt="Arab Scale Trading"-->
    <!--            >-->
    <!--        </td>-->

    <!--        <td class="address-cell">-->
    <!--            <img-->
    <!--                src="/private/files/arabscale_address.png"-->
    <!--                class="address-image"-->
    <!--                alt="Company Address"-->
    <!--            >-->
    <!--        </td>-->
    <!--    </tr>-->
    <!--</table>-->
    {% set fixed_letterhead = frappe.db.get_value(
    "Letter Head",
    "Arab Scale Letter Head - Standard",
    "content"
) %}

{% if fixed_letterhead %}
    <div class="hardcoded-letterhead">
        {{ fixed_letterhead }}
    </div>
{% endif %}
    
    <!-- Letterhead -->


    <!-- Invoice title -->
    <div class="title-row">
        <div class="title-line"></div>

        <h1 class="invoice-title">
            {% if doc.is_return %}
                CREDIT NOTE
            {% else %}
                TAX INVOICE
            {% endif %}
        </h1>

        <div class="title-line"></div>
    </div>

    <!-- Customer and invoice information -->
    <table class="information-table">
        <tr>
            <td class="customer-section">
                <div class="section-label">Bill To</div>

                <div class="customer-name">
                    {{ doc.customer_name or doc.customer }}
                </div>

                <div class="customer-address">
                    {% if doc.address_display %}
                        {{ doc.address_display }}
                    {% elif doc.customer_address %}
                        {{ doc.customer_address }}
                    {% endif %}
                </div>

                {% if doc.tax_id %}
                    <div style="margin-top: 4px;">
                        <strong>TRN:</strong> {{ doc.tax_id }}
                    </div>
                {% endif %}
            </td>

            <td class="invoice-info-section">
                <table class="invoice-details">
                    <tr>
                        <td class="detail-label">Invoice #</td>
                        <td class="detail-value">{{ doc.name }}</td>
                    </tr>

                    <tr>
                        <td class="detail-label">Invoice Date</td>
                        <td class="detail-value">
                            {{ frappe.utils.formatdate(doc.posting_date, "dd MMM yyyy") }}
                        </td>
                    </tr>

                    <tr>
                        <td class="detail-label">Terms</td>
                        <td class="detail-value">
                            {{ doc.payment_terms_template or doc.terms or "" }}
                        </td>
                    </tr>

                    <tr>
                        <td class="detail-label">P.O.#</td>
                        <td class="detail-value">
                            {{ doc.po_no or "" }}
                        </td>
                    </tr>

                    <tr>
                        <td class="detail-label">Sales Person</td>
                        <td class="detail-value">
                            {% if doc.sales_team and doc.sales_team|length > 0 %}
                                {{ doc.sales_team[0].sales_person }}
                            {% else %}
                                {{ doc.sales_partner or "" }}
                            {% endif %}
                        </td>
                    </tr>
                </table>
            </td>
        </tr>
    </table>

    <!-- Item table -->
    <table class="item-table">
        <thead>
            <tr>
                <th class="col-number">S.No</th>
                <th class="col-description">Item &amp; Description</th>
                <th class="col-qty">Qty</th>
                <th class="col-rate">Rate</th>
                <th class="col-tax-rate">Tax%</th>
                <th class="col-tax">Tax</th>
                <th class="col-amount">Amount</th>
            </tr>
        </thead>

        <tbody>
            {% for item in doc.items %}

                {% set taxable_amount = frappe.utils.flt(item.net_amount) %}
                {% set line_tax = taxable_amount * vat_rate / 100 %}
                {% set amount_with_tax = taxable_amount + line_tax %}

                <tr>
                    <td class="col-number">
                        {{ loop.index }}
                    </td>

                    <td class="col-description">
                        <div class="item-name">
                            {{ item.item_name or item.item_code }}
                        </div>

                        {% if item.description %}
                            <div class="item-description">
                                {{ item.description }}
                            </div>
                        {% endif %}

                        {% if item.serial_no %}
                            <div class="item-description">
                                Serial Number# {{ item.serial_no }}
                            </div>
                        {% endif %}

                        {% if item.batch_no %}
                            <div class="item-description">
                                Batch# {{ item.batch_no }}
                            </div>
                        {% endif %}
                    </td>

                    <td class="col-qty">
                        {{ frappe.utils.fmt_money(item.qty, precision=2) }}
                        {% if item.uom %}
                            <br>
                            <span style="font-size: 8px;">{{ item.uom }}</span>
                        {% endif %}
                    </td>

                    <td class="col-rate">
                        {{ frappe.utils.fmt_money(item.net_rate, precision=2) }}
                    </td>

                    <td class="col-tax-rate">
                        {{ frappe.utils.fmt_money(vat_rate, precision=0) }}
                    </td>

                    <td class="col-tax">
                        {{ frappe.utils.fmt_money(line_tax, precision=2) }}
                    </td>

                    <td class="col-amount">
                        {{ frappe.utils.fmt_money(amount_with_tax, precision=2) }}
                    </td>
                </tr>
            {% endfor %}
        </tbody>
    </table>

    <!-- Amount in words and totals -->
    <table class="summary-table">
        <tr>
            <td class="amount-words-section">
                <span class="amount-words-label">Amount in words :</span>

                <span class="amount-words-value">
                    {{ doc.in_words or "" }}
                </span>
            </td>

            <td class="totals-section">
                <table class="totals-table">
                    <tr>
                        <td class="totals-label">
                            Subtotal (Taxable Amount) {{ doc.currency }}
                        </td>

                        <td class="totals-value">
                            {{ frappe.utils.fmt_money(
                                doc.net_total,
                                precision=2
                            ) }}
                        </td>
                    </tr>

                    <tr>
                        <td class="totals-label">Discount</td>

                        <td class="totals-value">
                            {{ frappe.utils.fmt_money(
                                doc.discount_amount or 0,
                                precision=2
                            ) }}
                        </td>
                    </tr>

                    <tr>
                        <td class="totals-label">
                            VAT ({{ frappe.utils.fmt_money(vat_rate, precision=0) }}%):
                            {{ doc.currency }}
                        </td>

                        <td class="totals-value">
                            {{ frappe.utils.fmt_money(
                                doc.total_taxes_and_charges or 0,
                                precision=2
                            ) }}
                        </td>
                    </tr>

                    <tr class="grand-total-row">
                        <td class="totals-label">
                            Total (Incl. VAT)<br>
                            {{ doc.currency }}
                        </td>

                        <td class="totals-value grand-total-amount">
                            {{ doc.currency }}
                            {{ frappe.utils.fmt_money(
                                doc.grand_total,
                                precision=2
                            ) }}
                        </td>
                    </tr>
                </table>
            </td>
        </tr>
    </table>

    <!-- Terms and Conditions -->
    <div class="terms-section">
        <div class="terms-title">Terms &amp; Conditions</div>

        <div class="terms-content">
            {% if doc.terms %}
                {{ doc.terms }}
            {% else %}
                <div>Payment: Cash / Cheque against delivery.</div>
                <div>Delivery: Ex-stock (subject to prior sale).</div>
                <div>
                    Warranty: 12 Months from the date of Invoice
                    (against any manufacturing defect)
                </div>
            {% endif %}
        </div>

        <div class="thank-you">
            We take this opportunity to thank you for your enquiry,
            if you have any query please feel free to contact us.
        </div>

        <div class="signature">
            For {{ doc.company }},
        </div>
    </div>

</div>

{% set barcode_value = "" %}
{% if doc.barcodes and doc.barcodes|length > 0 %}
    {% set barcode_value = doc.barcodes[0].barcode %}
