                {% endif %}
                -->


                <div class="subject-section">
                    <div class="subject-label">
                        Subject :
                    </div>

                    <div class="subject-value">
                        {{ doc.custom_subject or doc.order_type or "" }}
                    </div>
                </div>

            </td>


            <td class="quotation-info-section">

                <table class="quotation-details">

                    <tr>
                        <td class="detail-label">
                            Date :
                        </td>

                        <td class="detail-value">
                            {{ frappe.utils.formatdate(
                                doc.transaction_date,
                                "dd MMM yyyy"
                            ) }}
                        </td>
                    </tr>


                    <tr>
                        <td class="detail-label">
                            Sales person :
                        </td>

                        <td class="detail-value">
                            {% if doc.sales_team and doc.sales_team|length > 0 %}
                                {{ doc.sales_team[0].sales_person }}
                            {% else %}
                                {{ doc.sales_partner or "" }}
                            {% endif %}
                        </td>
                    </tr>


                    <!--
                    Optional Valid Till

                    {% if doc.valid_till %}
                        <tr>
                            <td class="detail-label">
                                Valid Till :
                            </td>

                            <td class="detail-value">
                                {{ frappe.utils.formatdate(
                                    doc.valid_till,
                                    "dd MMM yyyy"
                                ) }}
                            </td>
                        </tr>
                    {% endif %}
                    -->


                    <!--
                    Optional Customer Reference

                    {% if doc.customer_name %}
                        <tr>
                            <td class="detail-label">
                                Customer :
                            </td>

                            <td class="detail-value">
                                {{ doc.customer_name }}
                            </td>
                        </tr>
                    {% endif %}
                    -->

                </table>

            </td>
        </tr>
    </table>


    <!-- ==================================================
         ITEM TABLE
         ================================================== -->

    <table class="item-table">
        <thead>
            <tr>
                <th class="col-number">
                    S<br>N
                </th>

                <th class="col-image"></th>

                <th class="col-description">
                    Item &amp; Description
                </th>

                <th class="col-qty">
                    Qty
                </th>

                <th class="col-rate">
                    Rate in<br>
                    {{ doc.currency }}
                </th>

                <th class="col-amount">
                    Amount
                </th>
            </tr>
        </thead>

        <tbody>
            {% for item in doc.items %}

                {% set master_item_image = frappe.db.get_value(
                    "Item",
                    item.item_code,
                    "image"
                ) %}

                {% set display_image = item.image or master_item_image %}

                <tr>
                    <td class="col-number">
                        {{ loop.index }}
                    </td>


                    <td class="col-image">
                        {% if display_image %}
                            <img
                                src="{{ display_image }}"
                                class="item-image"
                                alt="{{ item.item_name or item.item_code }}"
                            >
                        {% else %}

                            <!--
                            No-image placeholder is currently hidden.

                            To show it, uncomment below:

                            <div class="item-image-placeholder">
                                No Image
                            </div>
                            -->

                        {% endif %}
                    </td>


                    <td class="col-description">

                        <div class="item-name">
                            {{ item.item_name or item.item_code }}
                        </div>


                        <!--
                        Item code is currently hidden.

                        To show the item code, uncomment below:

                        {% if item.item_code %}
                            <div class="item-code">
                                {{ item.item_code }}
                            </div>
                        {% endif %}
                        -->


                        {% if item.description %}
                            <div class="item-description">
                                {{ item.description }}
                            </div>
                        {% endif %}


                        {% if item.serial_no %}
                            <div class="item-reference">
                                Serial Number#:
                                {{ item.serial_no | replace("\n", ", ") }}
                            </div>
                        {% endif %}


                        {% if item.batch_no %}
                            <div class="item-reference">
                                Batch#:
                                {{ item.batch_no }}
                            </div>
                        {% endif %}


                        <!--
                        Optional Supplier Quotation Reference

                        {% if item.supplier_quotation %}
                            <div class="item-reference">
                                Supplier Quotation:
                                {{ item.supplier_quotation }}
                            </div>
                        {% endif %}
                        -->

                    </td>


                    <td class="col-qty">
                        {{ frappe.utils.fmt_money(
                            item.qty,
                            precision=2
                        ) }}

                        {% if item.uom %}
                            <span class="quantity-uom">
                                {{ item.uom }}
                            </span>
                        {% endif %}
                    </td>


                    <td class="col-rate">
                        {{ frappe.utils.fmt_money(
                            item.net_rate or item.rate,
                            precision=2
                        ) }}
                    </td>


                    <td class="col-amount">
                        {{ frappe.utils.fmt_money(
                            item.net_amount or item.amount,
                            precision=2
                        ) }}
                    </td>
                </tr>

            {% endfor %}
        </tbody>
    </table>


    <!-- ==================================================
         TOTALS
         ================================================== -->

    <table class="summary-table">
        <tr>
            <td class="summary-empty-section"></td>

            <td class="totals-section">

                <table class="totals-table">

                    <tr>
                        <td class="totals-label">
                            Sub Total
                        </td>

                        <td class="totals-value">
                            {{ frappe.utils.fmt_money(
                                doc.net_total,
                                precision=2
                            ) }}
                        </td>
                    </tr>


                    {% if doc.discount_amount %}
                        <tr>
                            <td class="totals-label">
                                Discount
                            </td>

                            <td class="totals-value">
                                {{ frappe.utils.fmt_money(
                                    doc.discount_amount,
                                    precision=2
                                ) }}
                            </td>
                        </tr>
                    {% endif %}


                    <tr class="vat-row">
                        <td class="totals-label">
                            VAT
                            ({{ frappe.utils.fmt_money(
                                vat_rate,
                                precision=0
                            ) }}%)
                        </td>

                        <td class="totals-value">
                            {{ frappe.utils.fmt_money(
                                doc.total_taxes_and_charges or 0,
                                precision=2
                            ) }}
                        </td>
                    </tr>


                    <tr class="grand-total-row">
                        <td class="totals-label grand-total-label">
                            Total
                        </td>

                        <td class="totals-value grand-total-value">
                            {{ doc.currency }}
                            {{ frappe.utils.fmt_money(
                                doc.grand_total,
                                precision=2
                            ) }}
                        </td>
                    </tr>

                </table>

            </td>
        </tr>
    </table>


    <!-- ==================================================
         TOTAL IN WORDS
         ================================================== -->

    <table class="amount-words-table">
        <tr>
            <td class="amount-words-empty"></td>

            <td class="amount-words-label">
                Total In Words:
            </td>

            <td class="amount-words-value">
                {{ doc.in_words or "" }}
            </td>
        </tr>
    </table>


    <!-- ==================================================
         CUSTOMER NOTES
         ================================================== -->

    <div class="customer-notes-section">

        <div class="customer-notes-title">
            Customer Notes
        </div>

        <div class="customer-notes-content">

            {% if doc.custom_customer_notes %}
                {{ doc.custom_customer_notes }}

            {% else %}

                <div style="margin-bottom:6px;">
                    Bank Details:
                </div>

                <div>
                    - Account Name: Arab Scale Trading LLC
                </div>

                <div>
                    - Account No.: 0024214538061
                </div>

                <div>
                    - IBAN No.: AE33 0400 0000 2421 4538 061
                </div>

                <div>
                    - Swift Code: NRAKAEAK
                </div>

                <div>
                    - Bank Name: National Bank of Ras Al-Khaimah
                </div>

                <div>
                    - Branch: Sharjah
                </div>

            {% endif %}

        </div>
    </div>


    <!--
    Alternative dynamic bank details

    Create a custom HTML field named:
    custom_customer_notes

    Then enter the bank details in each Quotation.

    The active code above already checks:
    {{ doc.custom_customer_notes }}
    -->


    <!-- ==================================================
         TERMS AND CONDITIONS
         ================================================== -->

    <div class="terms-section">

        <div class="terms-title">
            Terms &amp; Conditions:
        </div>

        <div class="terms-content">

            {% if doc.terms %}
                {{ doc.terms }}

            {% else %}

                <div>
                    Payment: 100% advance
                </div>

                <div>
                    Delivery: Ex-stock (subject to prior sale).
                </div>

                <div>
                    Warranty: 12 Months from the date of Invoice
                    (against any manufacturing defect)
                </div>

            {% endif %}

        </div>


        <div class="thank-you">
            We take this opportunity to thank you for your enquiry,
            if you have any query please feel free to contact us.
        </div>


        <div class="authorized-signature">
            For {{ doc.company }},
        </div>

    </div>


    <!-- ==================================================
         FOOTER — OPTION 1

         Get footer from the fixed Letter Head.
         ================================================== -->

    {% set fixed_footer = frappe.db.get_value(
        "Letter Head",
        "Arab Scale Letter Head - Standard",
        "footer"
    ) %}

    {% if fixed_footer %}
        <div class="hardcoded-footer">
            {{ fixed_footer }}
        </div>
    {% endif %}


